GameData::Evolution.register({
  :id            => :Level,
  :parameter     => Integer,
  :level_up_proc => proc { |pkmn, parameter|
    next pkmn.level >= parameter
  }
})

GameData::Evolution.register({
  :id            => :AttackGreater,   # Hitmonlee
  :parameter     => Integer,
  :level_up_proc => proc { |pkmn, parameter|
    next pkmn.level >= parameter && pkmn.attack > pkmn.defense
  }
})

GameData::Evolution.register({
  :id            => :AtkDefEqual,   # Hitmontop
  :parameter     => Integer,
  :level_up_proc => proc { |pkmn, parameter|
    next pkmn.level >= parameter && pkmn.attack == pkmn.defense
  }
})

GameData::Evolution.register({
  :id            => :Silcoon,
  :parameter     => Integer,
  :level_up_proc => proc { |pkmn, parameter|
    next pkmn.level >= parameter && (((pkmn.personalID >> 16) & 0xFFFF) % 10) < 5
  }
})

GameData::Evolution.register({
  :id            => :Cascoon,
  :parameter     => Integer,
  :level_up_proc => proc { |pkmn, parameter|
    next pkmn.level >= parameter && (((pkmn.personalID >> 16) & 0xFFFF) % 10) >= 5
  }
})

GameData::Evolution.register({
  :id                   => :HoldItem,
  :parameter            => :Item,
  :any_level_up         => true,   # Needs any level up
  :level_up_proc        => proc { |pkmn, parameter|
    next pkmn.item == parameter
  },
  :after_evolution_proc => proc { |pkmn, new_species, parameter, evo_species|
    next false if evo_species != new_species || !pkmn.hasItem?(parameter)
    pkmn.item = nil   # Item is now consumed
    next true
  }
})

GameData::Evolution.register({
  :id            => :Item,
  :parameter     => :Item,
  :use_item_proc => proc { |pkmn, parameter, item|
    next item == parameter
  }
})

GameData::Evolution.register({
  :id                   => :TradeItem,
  :parameter            => :Item,
  :on_trade_proc        => proc { |pkmn, parameter, other_pkmn|
    next pkmn.item == parameter
  },
  :after_evolution_proc => proc { |pkmn, new_species, parameter, evo_species|
    next false if evo_species != new_species || !pkmn.hasItem?(parameter)
    pkmn.item = nil   # Item is now consumed
    next true
  }
})

GameData::Evolution.register({
  :id            => :TradeSpecies,
  :parameter     => :Species,
  :on_trade_proc => proc { |pkmn, parameter, other_pkmn|
    next pkmn.species == parameter && !other_pkmn.hasItem?(:EVERSTONE)
  }
})

GameData::Evolution.register({
  :id                => :BattleDealCriticalHit,
  :parameter         => Integer,
  :after_battle_proc => proc { |pkmn, party_index, parameter|
    next $game_temp.party_critical_hits_dealt &&
         $game_temp.party_critical_hits_dealt[party_index] &&
         $game_temp.party_critical_hits_dealt[party_index] >= parameter
  }
})

GameData::Evolution.register({
  :id         => :Event,
  :parameter  => Integer,
  :event_proc => proc { |pkmn, parameter, value|
    next value == parameter
  }
})

def species=(species_id)
  new_species_data = GameData::Species.get(species_id)
  return if @species == new_species_data.species
  @species     = new_species_data.species
  default_form = new_species_data.default_form
  if default_form >= 0
    @form      = default_form
  elsif new_species_data.form > 0
    @form      = new_species_data.form
  end
  @forced_form = nil
  @gender      = nil if singleGendered?
  @level       = nil   # In case growth rate is different for the new species
  @ability     = nil
  calc_stats
end

def pbStartScreen(pokemon, newspecies)
  @pokemon = pokemon
  @newspecies = newspecies
  @sprites = {}
  @bgviewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
  @bgviewport.z = 99999
  @viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
  @viewport.z = 99999
  @msgviewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
  @msgviewport.z = 99999
  addBackgroundOrColoredPlane(@sprites, "background", "evolution_bg",
                              Color.new(248, 248, 248), @bgviewport)
  rsprite1 = PokemonSprite.new(@viewport)
  rsprite1.setOffset(PictureOrigin::CENTER)
  rsprite1.setPokemonBitmap(@pokemon, false)
  rsprite1.x = Graphics.width / 2
  rsprite1.y = (Graphics.height - 64) / 2
  rsprite2 = PokemonSprite.new(@viewport)
  rsprite2.setOffset(PictureOrigin::CENTER)
  rsprite2.setPokemonBitmapSpecies(@pokemon, @newspecies, false)
  rsprite2.x       = rsprite1.x
  rsprite2.y       = rsprite1.y
  rsprite2.visible = false
  @sprites["rsprite1"] = rsprite1
  @sprites["rsprite2"] = rsprite2
  @sprites["msgwindow"] = pbCreateMessageWindow(@msgviewport)
  set_up_animation
  pbFadeInAndShow(@sprites) { pbUpdate }
end

def pbFlashInOut(canceled)
  timer_start = System.uptime
  loop do
    Graphics.update
    pbUpdate(true)
    pbUpdateExpandScreen(timer_start)
    tone = lerp(0, 255, 0.7, timer_start, System.uptime)
    @viewport.tone.set(tone, tone, tone, 0)
    break if tone >= 255
  end
  @bgviewport.rect.y      = 0
  @bgviewport.rect.height = Graphics.height
  @sprites["background"].oy = 0
  if canceled
    @sprites["rsprite1"].visible     = true
    @sprites["rsprite1"].zoom_x      = 1.0
    @sprites["rsprite1"].zoom_y      = 1.0
    @sprites["rsprite1"].color.alpha = 0
    @sprites["rsprite2"].visible     = false
  else
    @sprites["rsprite1"].visible     = false
    @sprites["rsprite2"].visible     = true
    @sprites["rsprite2"].zoom_x      = 1.0
    @sprites["rsprite2"].zoom_y      = 1.0
    @sprites["rsprite2"].color.alpha = 0
  end
  timer_start = System.uptime
  loop do
    Graphics.update
    pbUpdate(true)
    break if System.uptime - timer_start >= 0.25
  end
  timer_start = System.uptime
  loop do
    Graphics.update
    pbUpdate
    pbUpdateExpandScreen(timer_start)
    tone = lerp(255, 0, 0.4, timer_start, System.uptime)
    @viewport.tone.set(tone, tone, tone, 0)
    break if tone <= 0
  end
end

def pbEvolutionMethodAfterEvolution
  @pokemon.action_after_evolution(@newspecies)
end

def pbEndScreen(need_fade_out = true)
  pbDisposeMessageWindow(@sprites["msgwindow"]) if @sprites["msgwindow"]
  if need_fade_out
    pbFadeOutAndHide(@sprites) { pbUpdate }
  end
  pbDisposeSpriteHash(@sprites)
  @viewport.dispose
  @bgviewport.dispose
  @msgviewport.dispose
end

ItemHandlers::UseOnPokemonMaximum.add(:RARECANDY, proc { |item, pkmn|
  next GameData::GrowthRate.max_level - pkmn.level
})

def self.isDay?(time = nil)
  time = pbGetTimeNow if !time
  return (time.hour >= 5 && time.hour < 20)
end

def self.isNight?(time = nil)
  time = pbGetTimeNow if !time
  return (time.hour >= 20 || time.hour < 5)
end

def self.isMorning?(time = nil)
  time = pbGetTimeNow if !time
  return (time.hour >= 5 && time.hour < 10)
end

def self.isAfternoon?(time = nil)
  time = pbGetTimeNow if !time
  return (time.hour >= 14 && time.hour < 17)
end

def self.isEvening?(time = nil)
  time = pbGetTimeNow if !time
  return (time.hour >= 17 && time.hour < 20)
end

def weather(type, power, duration)
  @weather_type     = GameData::Weather.get(type).id
  @weather_max      = (power + 1) * RPG::Weather::MAX_SPRITES / 10
  @weather_duration = duration
end

def has_flag?(flag)
  return @flags.any? { |f| f.downcase == flag.downcase }
end

def pbStartScreen(pokemon, pokemon2, trader1, trader2)
  @sprites = {}
  @viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
  @viewport.z = 99999
  @pokemon  = pokemon
  @pokemon2 = pokemon2
  @trader1  = trader1
  @trader2  = trader2
  addBackgroundOrColoredPlane(@sprites, "background", "trade_bg",
                              Color.new(248, 248, 248), @viewport)
  @sprites["rsprite1"] = PokemonSprite.new(@viewport)
  @sprites["rsprite1"].setPokemonBitmap(@pokemon, false)
  @sprites["rsprite1"].setOffset(PictureOrigin::BOTTOM)
  @sprites["rsprite1"].x = Graphics.width / 2
  @sprites["rsprite1"].y = 264
  @sprites["rsprite1"].z = 10
  @pokemon.species_data.apply_metrics_to_sprite(@sprites["rsprite1"], 1)
  @sprites["rsprite2"] = PokemonSprite.new(@viewport)
  @sprites["rsprite2"].setPokemonBitmap(@pokemon2, false)
  @sprites["rsprite2"].setOffset(PictureOrigin::BOTTOM)
  @sprites["rsprite2"].x = Graphics.width / 2
  @sprites["rsprite2"].y = 264
  @sprites["rsprite2"].z = 10
  @pokemon2.species_data.apply_metrics_to_sprite(@sprites["rsprite2"], 1)
  @sprites["rsprite2"].visible = false
  @sprites["msgwindow"] = pbCreateMessageWindow(@viewport)
  pbFadeInAndShow(@sprites)
end

def hp=(value)
  @hp = value.clamp(0, @totalhp)
  heal_status if @hp == 0
  @ready_to_evolve = false if @hp == 0
end

def pokemon_party
  return @party.find_all { |p| p && !p.egg? }
end

def able_party
  return @party.find_all { |p| p && !p.egg? && !p.fainted? }
end

def pbChoosePokemonForTrade(variableNumber, nameVarNumber, wanted)
  wanted = GameData::Species.get(wanted).species
  pbChooseTradablePokemon(variableNumber, nameVarNumber, proc { |pkmn|
    next pkmn.species == wanted
  })
end

def pbFaint(showMessage = true)
  if !fainted?
    PBDebug.log("!!!***Can't faint with HP greater than 0")
    return
  end
  return if @fainted   # Has already fainted properly
  @battle.pbDisplayBrief(_INTL("{1} fainted!", pbThis)) if showMessage
  PBDebug.log("[Pokémon fainted] #{pbThis} (#{@index})") if !showMessage
  @battle.scene.pbFaintBattler(self)
  @battle.pbSetDefeated(self) if opposes?
  pbInitEffects(false)
  # Reset status
  self.status      = :NONE
  self.statusCount = 0
  # Lose happiness
  if @pokemon && @battle.internalBattle
    badLoss = @battle.allOtherSideBattlers(@index).any? { |b| b.level >= self.level + 30 }
    @pokemon.changeHappiness((badLoss) ? "faintbad" : "faint")
  end
  # Reset form
  @battle.peer.pbOnLeavingBattle(@battle, @pokemon, @battle.usedInBattle[idxOwnSide][@index / 2])
  @pokemon.makeUnmega if mega?
  @pokemon.makeUnprimal if primal?
  # Do other things
  @battle.pbClearChoice(@index)   # Reset choice
  pbOwnSide.effects[PBEffects::LastRoundFainted] = @battle.turnCount
  if $game_temp.party_direct_damage_taken &&
     $game_temp.party_direct_damage_taken[@pokemonIndex] &&
     pbOwnedByPlayer?
    $game_temp.party_direct_damage_taken[@pokemonIndex] = 0
  end
  # Check other battlers' abilities that trigger upon a battler fainting
  pbAbilitiesOnFainting
  # Check for end of primordial weather
  @battle.pbEndPrimordialWeather
end
